
.status-shell {
  position: relative;
  width: 100%;
  max-width: 1080px;
  margin: 0 auto;
  padding: 18px;
  background: linear-gradient(180deg, rgba(142, 255, 202, 0.05), transparent 18%), rgba(4, 13, 11, 0.92);
  border: 1px solid var(--terminal-line);
  border-radius: 24px;
  box-shadow: var(--terminal-shadow);
  overflow: hidden;
  display: grid;
  gap: 14px;
}

.status-shell::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(transparent 0, rgba(255, 255, 255, 0.03) 50%, transparent 100%),
    repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.02) 0, rgba(255, 255, 255, 0.02) 1px, transparent 1px, transparent 4px);
  mix-blend-mode: screen;
  opacity: 0.16;
}

.status-head,
.board-grid,
.status-foot {
  position: relative;
  z-index: 1;
}

.status-head {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(320px, 1fr);
  gap: 14px;
}

.eyebrow,
.meta-label {
  font: 600 11px var(--font-mono);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--terminal-muted);
}

.title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin: 6px 0 8px;
}

.title-row h1 {
  margin: 0;
  font-size: clamp(28px, 5vw, 42px);
  line-height: 1;
}

.head-copy p {
  margin: 0;
  color: var(--terminal-muted);
  font-size: 14px;
}

.meta-grid {
  display: grid;
  gap: 10px;
}

.meta-card {
  padding: 12px 14px;
  background: linear-gradient(135deg, rgba(15, 36, 31, 0.95), rgba(10, 24, 21, 0.88));
  border: 1px solid var(--terminal-line);
  border-radius: 16px;
  display: grid;
  gap: 4px;
}

.meta-card strong {
  font-size: 15px;
}

.meta-card span:last-child {
  color: var(--terminal-muted);
  font-size: 12px;
}

.board-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
}

.panel {
  padding: 14px;
  background: linear-gradient(180deg, rgba(15, 35, 30, 0.94), rgba(10, 23, 20, 0.92));
  border: 1px solid var(--terminal-line);
  border-radius: 18px;
  min-width: 0;
}

.span-8 {
  grid-column: span 8;
}

.span-6 {
  grid-column: span 6;
}

.span-4 {
  grid-column: span 4;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(127, 255, 214, 0.1);
  font: 600 12px var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.panel-head strong {
  font-size: 12px;
  color: var(--terminal-accent);
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.metric-card,
.resource-card {
  padding: 12px;
  background: rgba(5, 18, 15, 0.88);
  border: 1px solid rgba(127, 255, 214, 0.09);
  border-radius: 14px;
  display: grid;
  gap: 4px;
}

.metric-card span,
.resource-card span {
  color: var(--terminal-muted);
  font-size: 12px;
}

.metric-card strong,
.resource-card strong {
  font-size: 18px;
}

.metric-card small {
  color: var(--terminal-muted);
  font-size: 12px;
}

.resource-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.phase-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  font: 700 11px var(--font-mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.phase-chip.safe {
  color: var(--terminal-accent);
  background: rgba(142, 255, 202, 0.09);
  border-color: rgba(142, 255, 202, 0.2);
}

.phase-chip.warn {
  color: var(--terminal-warn);
  background: rgba(255, 209, 102, 0.08);
  border-color: rgba(255, 209, 102, 0.22);
}

.phase-chip.danger {
  color: var(--terminal-danger);
  background: rgba(255, 125, 125, 0.08);
  border-color: rgba(255, 125, 125, 0.2);
}

.list-stack {
  display: grid;
  gap: 10px;
}

.list-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(5, 18, 15, 0.84);
  border: 1px solid rgba(127, 255, 214, 0.08);
}

.list-row.alert {
  border-color: rgba(255, 209, 102, 0.18);
}

.list-row strong {
  display: block;
  margin-bottom: 4px;
}

.list-row p {
  margin: 0;
  color: var(--terminal-muted);
  font-size: 12px;
  line-height: 1.5;
}

.row-meta {
  display: grid;
  justify-items: end;
  gap: 6px;
  color: var(--terminal-muted);
  font-size: 12px;
}

.status-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--terminal-muted);
  font: 600 11px var(--font-mono);
  letter-spacing: 0.08em;
  padding-top: 12px;
  border-top: 1px solid rgba(127, 255, 214, 0.12);
}

@media (max-width: 960px) {
  .status-head,
  .metric-grid,
  .resource-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .status-head {
    grid-template-columns: 1fr;
  }

  .span-8,
  .span-6,
  .span-4 {
    grid-column: span 12;
  }
}

@media (max-width: 720px) {
  .status-shell {
    padding: 14px;
    border-radius: 18px;
  }

  .metric-grid,
  .resource-grid {
    grid-template-columns: 1fr;
  }

  .panel-head,
  .status-foot,
  .list-row {
    grid-template-columns: 1fr;
    flex-direction: column;
    align-items: start;
  }

  .panel-head {
    display: grid;
  }

  .row-meta {
    justify-items: start;
  }
}
